"""Rebuild the canonical reader once; extend its home without duplicating lessons."""
from pathlib import Path
import importlib.util
import json
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('canonical_reader',ROOT/'scripts/build_reader_v9.py')
b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)

def main():
    b.main()
    evidence=json.loads((ROOT/'reports/v12/summary.json').read_text())
    refs=evidence['references_passed'];tests=evidence['tests']['passed'];skips=evidence['tests']['skipped']
    home=ROOT/'START_HERE.html'
    href=lambda x:b.esc(b.relative(b.destination(ROOT/x),ROOT))
    topics=[('R01','Covariance and whitening','Start with actual observations; distinguish shape, moments, and distributions.'),('R02','Random projections and SIGReg','Derive a characteristic-function score and test what finite sketches miss.'),('R03','How self-supervised objectives work','Inspect agreement, VICReg, Barlow Twins, InfoNCE, EMA, and stop-gradient.'),('R04','Train, probe, and question the result','Run a two-seed digit experiment with ordinary baselines and saved predictions.'),('R05','Transfer to sports and other industries','Preserve identities, timing, units, and evidence before claiming a world model.')]
    primary=''.join(f'<a class="card" data-search="{b.esc(s["id"]+" "+s["title"]+" "+s["track"])}" href="{href("curriculum/stages/"+s["id"]+".md")}"><span>STAGE {s["id"]} · {b.esc(s["track"])}</span><h3>{b.esc(s["title"])}</h3><p>{b.esc(s["gate"])}</p></a>' for s in b.CAT['stages'])
    reps=''.join(f'<a class="card" href="{href("representations/lessons/"+key+".md")}"><span>{key} · REPRESENTATIONS</span><h3>{b.esc(title)}</h3><p>{b.esc(desc)}</p></a>' for key,title,desc in topics)
    body=f'''<p class="eyebrow">Version 12 · One course · Evidence-backed execution</p><h1>Learn shape.<br>Build understanding.</h1><p>Begin with observations and notation. Build through topology, geometry, dynamics, and representation learning. Test ideas with real data from different industries and sports.</p><p class="notice"><strong>New learner:</strong> start Stage 00. <strong>Continuing learner:</strong> keep your answers and resume your next unassessed lesson. Running code does not automatically assess mastery.</p><div class="cards"><a class="card" href="{href('docs/release/FIRST_RUN.md')}"><span>START SIMPLY</span><h3>Git + uv + your first experiment</h3><p>Read without installation. Use a fresh environment when you are ready to execute.</p></a><a class="card" href="{href('curriculum/SITUATIONS.md')}"><span>CHOOSE A PATH</span><h3>Which situation are you facing?</h3><p>Definitions, noisy data, leakage, geometry, prediction, or a failed physical assumption.</p></a><a class="card" href="{href('docs/release/KUBERNETES.md')}"><span>DEPLOYMENT PRACTICE</span><h3>Docker to Kubernetes</h3><p>Learn Pods, Jobs, persistent volumes, safe contexts, and explicit acceptance evidence.</p></a><a class="card" href="{href('docs/release/VERIFICATION.md')}"><span>WHAT ACTUALLY RAN</span><h3>{refs} references · {tests} tests passed</h3><p>{skips} optional-library checks skipped. Open the evidence and remaining deployment gates.</p></a></div><p class="notice"><strong>Deployment status:</strong> local Python experiments passed. A fresh uv installation, Docker image execution, and a live Kubernetes cluster remain blocked on this build host. Kubernetes project-policy checks are not server validation or a successful Job.</p><h2>Representation learning: continue after the foundation</h2><p>Five units build on the core instead of repeating it. Understand the supplied SIGReg / JEPA terminology, test the mathematics, and train a small encoder with interpretable comparisons.</p><div class="cards">{reps}</div><h2>One acceptance command, honest scope</h2><pre><code>uv run --no-sync python course.py acceptance --profile physics --references first --output my_work/acceptance01</code></pre><p>The report validates test counts, notebook identities and unchanged inputs. It does not claim a clean installation, container deployment or learner mastery. All 25 case practice commands now have editable private-copy destinations. Begin with <code>course.py practice 0 --output my_work/practice00</code>.</p><h2>The 31-stage primary route</h2><p>One primary lesson per stage. Read, calculate, predict, execute, and then solve the independent assignment. Primers and answers have separate roles.</p><label for="stage-search">Find a core topic</label><br><input class="search" id="stage-search" type="search" placeholder="Try homology, camera, dynamics, or 06"><p id="search-count" class="muted" aria-live="polite">31 stages</p><div class="cards">{primary}</div><h2>Apply the same foundations</h2><p><a href="{href('curriculum/APPLICATIONS.md')}">Industry and sports cases</a> · <a href="{href('docs/release/SPORTS_REFRESH.md')}">Dated sports-source update</a> · <a href="{href('representations/SOURCE_AUDIT.md')}">SIGReg source audit</a> · <a href="{href('representations/TERMINOLOGY.md')}">Terminology lookup</a> · <a href="{href('docs/release/AGENT_HANDOFF.md')}">Copy/paste repository handoff</a></p><p class="muted">Reference notebooks include executed outputs. Required snapshots are bundled; optional large datasets and model weights are not downloaded silently. No fonts, publisher book, or credentials are included.</p>'''
    js='''<script>(()=>{const q=document.getElementById('stage-search'),cards=[...document.querySelectorAll('[data-search]')];q.addEventListener('input',()=>{let n=0;for(const c of cards){c.hidden=!c.dataset.search.toLowerCase().includes(q.value.toLowerCase());if(!c.hidden)n++}document.getElementById('search-count').textContent=n+' matching stages'});})();</script>'''
    home.write_text(b.shell('Course home v12',body,home,js=js))
    report={'release':'12.0.0','core_primary_lessons':31,'representation_primary_lessons':5,'reference_notebooks':133,'source_build_report':'reports/release/reader_build.json'}
    (ROOT/'reports/v12/reader_build.json').write_text(json.dumps(report,indent=2)+'\n')
if __name__=='__main__':main()
